import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { ShieldCheck, Fingerprint, ArrowRight, Lock, User, Cpu } from 'lucide-react';

const WorkerSignIn = () => {
  const [isScanning, setIsScanning] = useState(false);

  const handleAuth = () => {
    setIsScanning(true);
    // Simulate biometric delay
    setTimeout(() => { /* login logic */ }, 2000);
  };

  return (
    <div className="h-screen w-full bg-[#FDFAD8] flex items-center justify-center overflow-hidden relative">

      {/* Background Decorative Element - Soft "Neo" Glow */}
      <div className="absolute w-[800px] h-[800px] bg-[#CAD23C]/20 rounded-full blur-[120px] -top-96 -left-96 animate-pulse" />

      <motion.div 
        initial={{ opacity: 0, scale: 0.9, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
        className="relative w-full max-w-[460px] bg-white/40 backdrop-blur-3xl rounded-[60px] border border-white p-12 shadow-[0_40px_80px_rgba(71,81,11,0.05)]"
      >
        {/* Top Header */}
        <div className="flex flex-col items-center mb-12">
          <div className="w-20 h-20 bg-[#47510B] rounded-[28px] flex items-center justify-center shadow-2xl mb-6 relative group overflow-hidden">
            <div className="absolute inset-0 bg-gradient-to-tr from-[#CAD23C]/20 to-transparent" />
            <Cpu size={38} className="text-[#CAD23C] relative z-10" />
          </div>
          <h2 className="text-4xl font-[1000] italic text-[#47510B] uppercase tracking-tighter text-center">
            System <br/> <span className="text-[#FF5B03]">Access.</span>
          </h2>
          <p className="text-[10px] font-black text-[#47510B]/40 uppercase tracking-[0.4em] mt-2">Vanguard_Protocol_v4</p>
        </div>

        {/* Input Group - Ultra Clean Neo Style */}
        <div className="space-y-6">
          <div className="relative group">
            <User className="absolute left-6 top-1/2 -translate-y-1/2 text-[#47510B]/30 group-focus-within:text-[#FF5B03] transition-colors" size={20} />
            <input 
              type="text" 
              placeholder="OPERATOR_ID" 
              className="w-full bg-white/60 border border-white/80 p-6 pl-16 rounded-[28px] font-bold text-[#47510B] outline-none focus:ring-4 ring-[#CAD23C]/20 transition-all placeholder-[#47510B]/20" 
            />
          </div>

          <div className="relative group">
            <Lock className="absolute left-6 top-1/2 -translate-y-1/2 text-[#47510B]/30 group-focus-within:text-[#FF5B03] transition-colors" size={20} />
            <input 
              type="password" 
              placeholder="SECURITY_KEY" 
              className="w-full bg-white/60 border border-white/80 p-6 pl-16 rounded-[28px] font-bold text-[#47510B] outline-none focus:ring-4 ring-[#CAD23C]/20 transition-all placeholder-[#47510B]/20" 
            />
          </div>

          <motion.button 
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            onClick={handleAuth}
            className="w-full bg-[#47510B] text-white p-6 rounded-[28px] flex items-center justify-center gap-4 shadow-xl shadow-[#47510B]/20 relative overflow-hidden group"
          >
            {/* The "Scanning" Line for the Button */}
            {isScanning && (
              <motion.div 
                initial={{ left: '-100%' }}
                animate={{ left: '100%' }}
                transition={{ duration: 1.5, repeat: Infinity, ease: "linear" }}
                className="absolute top-0 bottom-0 w-1/2 bg-gradient-to-r from-transparent via-[#CAD23C]/30 to-transparent skew-x-12" 
              />
            )}

            <span className="font-black uppercase tracking-[0.2em] italic text-xl">
              {isScanning ? 'Verifying...' : 'Initialize'}
            </span>
            {!isScanning && <Fingerprint size={28} className="text-[#CAD23C]" />}
          </motion.button>
        </div>

        {/* Footer Info */}
        <div className="mt-10 flex flex-col items-center gap-2">
            <div className="flex items-center gap-2">
                <ShieldCheck size={14} className="text-[#CAD23C]" />
                <span className="text-[9px] font-black text-[#47510B]/40 uppercase tracking-widest">End-to-End Encrypted Node</span>
            </div>
        </div>
      </motion.div>
    </div>
  );
};

export default WorkerSignIn;
